INSERT INTO public.daily_quote_translations(quote_rotation_order,language_code,content) VALUES
  (1,'vi','Mỗi bình minh là một lời mời để mình yêu cuộc đời thêm một chút.'),
  (1,'en','Life still offers lovely things when we stay open to them. Let yourself move one beat more slowly.'),
  (1,'ja','心を開けば、人生にはまだ愛おしいものがあります。 もう一拍ゆっくり進んでみましょう。'),
  (1,'fr','La vie offre encore de belles choses quand on reste ouvert. Autorisez-vous à avancer un peu plus lentement.'),
  (1,'es','La vida aún ofrece cosas bonitas cuando nos abrimos a ellas. Permítete avanzar un poco más despacio.'),
  (1,'it','La vita offre ancora cose belle quando restiamo aperti. Concediti di procedere un po’ più lentamente.'),
  (1,'de','Das Leben hält Schönes bereit, wenn wir offen bleiben. Erlaube dir, einen Moment langsamer zu gehen.'),
  (1,'ko','마음을 열면 삶에는 여전히 사랑스러운 일이 있습니다. 한 박자 더 천천히 움직여도 괜찮습니다.'),
  (1,'pt','A vida ainda oferece beleza quando permanecemos abertos. Permita-se caminhar um pouco mais devagar.'),
  (1,'ms','Hidup masih menawarkan perkara indah apabila kita terbuka. Benarkan diri bergerak sedikit lebih perlahan.'),
  (1,'id','Hidup masih menawarkan hal indah saat kita mau terbuka. Izinkan dirimu bergerak sedikit lebih lambat.'),
  (1,'th','ชีวิตยังมีสิ่งน่ารักเสมอเมื่อเราเปิดใจรับมัน ให้ตัวเองเดินช้าลงอีกนิด'),
  (2,'vi','Cuộc sống dịu dàng hơn khi ta học cách trân trọng những điều rất nhỏ.'),
  (2,'en','Life still offers lovely things when we stay open to them. You do not have to make everything perfect today.'),
  (2,'ja','心を開けば、人生にはまだ愛おしいものがあります。 今日すべてを完璧にしなくても大丈夫です。'),
  (2,'fr','La vie offre encore de belles choses quand on reste ouvert. Tout n’a pas besoin d’être parfait aujourd’hui.'),
  (2,'es','La vida aún ofrece cosas bonitas cuando nos abrimos a ellas. Hoy no tienes que hacerlo todo perfecto.'),
  (2,'it','La vita offre ancora cose belle quando restiamo aperti. Oggi non deve essere tutto perfetto.'),
  (2,'de','Das Leben hält Schönes bereit, wenn wir offen bleiben. Heute muss nicht alles perfekt sein.'),
  (2,'ko','마음을 열면 삶에는 여전히 사랑스러운 일이 있습니다. 오늘 모든 것을 완벽하게 할 필요는 없습니다.'),
  (2,'pt','A vida ainda oferece beleza quando permanecemos abertos. Hoje não precisa ser tudo perfeito.'),
  (2,'ms','Hidup masih menawarkan perkara indah apabila kita terbuka. Hari ini tidak perlu semuanya sempurna.'),
  (2,'id','Hidup masih menawarkan hal indah saat kita mau terbuka. Hari ini tidak harus sempurna semuanya.'),
  (2,'th','ชีวิตยังมีสิ่งน่ารักเสมอเมื่อเราเปิดใจรับมัน วันนี้ไม่จำเป็นต้องทำทุกอย่างให้สมบูรณ์แบบ'),
  (3,'vi','Hôm nay vẫn đáng yêu, chỉ cần mình chịu mở lòng để nhìn thấy.'),
  (3,'en','Life still offers lovely things when we stay open to them. A small thing is still worthy of care.'),
  (3,'ja','心を開けば、人生にはまだ愛おしいものがあります。 小さなことにも大切にする価値があります。'),
  (3,'fr','La vie offre encore de belles choses quand on reste ouvert. Une petite chose mérite aussi votre attention.'),
  (3,'es','La vida aún ofrece cosas bonitas cuando nos abrimos a ellas. Lo pequeño también merece cuidado.'),
  (3,'it','La vita offre ancora cose belle quando restiamo aperti. Anche una cosa piccola merita cura.'),
  (3,'de','Das Leben hält Schönes bereit, wenn wir offen bleiben. Auch etwas Kleines verdient deine Aufmerksamkeit.'),
  (3,'ko','마음을 열면 삶에는 여전히 사랑스러운 일이 있습니다. 작은 일도 충분히 소중합니다.'),
  (3,'pt','A vida ainda oferece beleza quando permanecemos abertos. Uma coisa pequena também merece cuidado.'),
  (3,'ms','Hidup masih menawarkan perkara indah apabila kita terbuka. Perkara kecil juga layak dihargai.'),
  (3,'id','Hidup masih menawarkan hal indah saat kita mau terbuka. Hal kecil pun layak dirawat.'),
  (3,'th','ชีวิตยังมีสิ่งน่ารักเสมอเมื่อเราเปิดใจรับมัน เรื่องเล็ก ๆ ก็มีค่าควรได้รับการดูแล'),
  (4,'vi','Có những ngày bình thường nhưng vẫn đủ đẹp để ta biết ơn.'),
  (4,'en','Life still offers lovely things when we stay open to them. Gratitude can warm an ordinary day.'),
  (4,'ja','心を開けば、人生にはまだ愛おしいものがあります。 感謝は何気ない一日を温めます。'),
  (4,'fr','La vie offre encore de belles choses quand on reste ouvert. La gratitude réchauffe les jours ordinaires.'),
  (4,'es','La vida aún ofrece cosas bonitas cuando nos abrimos a ellas. La gratitud calienta los días normales.'),
  (4,'it','La vita offre ancora cose belle quando restiamo aperti. La gratitudine scalda i giorni normali.'),
  (4,'de','Das Leben hält Schönes bereit, wenn wir offen bleiben. Dankbarkeit macht gewöhnliche Tage warm.'),
  (4,'ko','마음을 열면 삶에는 여전히 사랑스러운 일이 있습니다. 감사는 평범한 하루를 따뜻하게 합니다.'),
  (4,'pt','A vida ainda oferece beleza quando permanecemos abertos. A gratidão aquece os dias comuns.'),
  (4,'ms','Hidup masih menawarkan perkara indah apabila kita terbuka. Syukur menghangatkan hari biasa.'),
